import{_ as t,o as r,c as o,a3 as s}from"./chunks/framework.Ki30n65y.js";const a="/depgate/screenshots/settings-repositories.png",i="/depgate/screenshots/repository-add.png",u=JSON.parse('{"title":"Repositories","description":"","frontmatter":{},"headers":[],"relativePath":"admin/repositories.md","filePath":"admin/repositories.md"}'),n={name:"admin/repositories.md"};function d(l,e,c,p,h,g){return r(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="repositories" tabindex="-1">Repositories <a class="header-anchor" href="#repositories" aria-label="Permalink to &quot;Repositories&quot;">​</a></h1><p>A <strong>repository</strong> is a URL that package clients use, such as <code>https://depgate.example.com/npm/default/</code>. Repositories decide which upstream registries DepGate asks for a package. Manage them under <strong>Settings → Repositories</strong> (Security role).</p><p><img src="'+a+'" alt="Repositories for npm, with the gateway security controls"></p><h2 id="kinds-of-repositories" tabindex="-1">Kinds of repositories <a class="header-anchor" href="#kinds-of-repositories" aria-label="Permalink to &quot;Kinds of repositories&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Kind</th><th>What it does</th><th>Example</th></tr></thead><tbody><tr><td><strong>Remote</strong></td><td>Proxies one upstream registry, public or internal.</td><td><code>default</code> → registry.npmjs.org; <code>acme-internal</code> → your Artifactory</td></tr><tr><td><strong>Virtual</strong></td><td>Serves several remotes behind one URL and asks them in order.</td><td><code>frontend</code> → <code>acme-internal</code>, then <code>default</code></td></tr></tbody></table><p>Every ecosystem starts with two reserved repositories:</p><ul><li><strong><code>default</code></strong>: the ecosystem&#39;s public registry.</li><li><strong><code>all</code></strong>: a virtual repository over every enabled remote of the ecosystem. New remotes join it automatically.</li></ul><p>Both can be disabled but not deleted. A disabled repository rejects client requests.</p><p>Choose <strong>Client setup</strong> to open the <a href="./../developers/connect-package-managers">Registry</a> page with the settings a developer needs for the selected ecosystem.</p><h2 id="add-a-remote-repository" tabindex="-1">Add a remote repository <a class="header-anchor" href="#add-a-remote-repository" aria-label="Permalink to &quot;Add a remote repository&quot;">​</a></h2><p>Use a remote to connect an internal registry (Artifactory, Nexus, Verdaccio, GitHub Packages, GitLab, Azure Artifacts) or another public mirror.</p><ol><li><p>Choose the ecosystem on the left, then <strong>Add repository</strong>. The form opens on its own page, with a summary on the right that shows the client URL as you type.</p></li><li><p>Fill in the form:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><strong>Type</strong></td><td><strong>Remote</strong>.</td></tr><tr><td><strong>Key</strong></td><td>A short lowercase name. It becomes part of the client URL, for example <code>/npm/acme-internal/</code>. <code>default</code> and <code>all</code> are reserved.</td></tr><tr><td><strong>Description</strong> (optional)</td><td>Shown in the list and on the Registry page.</td></tr><tr><td><strong>Upstream URL</strong></td><td>The registry&#39;s base URL, for example <code>https://artifactory.example.com/api/npm/npm-internal</code>.</td></tr><tr><td><strong>Source</strong></td><td><strong>Internal registry</strong> for registries that hold your own packages, <strong>Public registry</strong> for everything else. See <a href="#remote-source">Remote source</a>.</td></tr><tr><td><strong>Timeout (ms)</strong> and <strong>Retries</strong></td><td>How long to wait for the upstream, and how often to retry.</td></tr><tr><td><strong>Upstream authentication</strong></td><td>None, Basic (user name and password), Bearer token, or a custom header. Credentials are stored encrypted.</td></tr></tbody></table></li><li><p>Choose <strong>Create repository</strong>. The page stays open and offers <strong>Open client setup</strong>, which opens the <a href="./../developers/connect-package-managers">Registry</a> page on this repository&#39;s snippet.</p></li></ol><p><img src="'+i+'" alt="Adding a repository"></p><p>Choose the <strong>Test connection</strong> icon on the row to check that DepGate can reach the upstream with those settings.</p><h2 id="add-a-virtual-repository" tabindex="-1">Add a virtual repository <a class="header-anchor" href="#add-a-virtual-repository" aria-label="Permalink to &quot;Add a virtual repository&quot;">​</a></h2><p>Use a virtual repository to give a team one URL over several remotes, for example your internal registry first and the public registry second.</p><ol><li>Choose <strong>Add repository</strong> and set <strong>Type</strong> to <strong>Virtual</strong>.</li><li>Enter a key and select the member remotes.</li><li>Put them in the <strong>Search order</strong> you want with the up and down arrows.</li><li>Choose <strong>Create repository</strong>.</li></ol><h3 id="search-order" tabindex="-1">Search order <a class="header-anchor" href="#search-order" aria-label="Permalink to &quot;Search order&quot;">​</a></h3><p>A virtual repository asks its remotes in order, and the first one that has the package serves it. The same applies to <code>all</code>; edit it to change its order.</p><ul><li><strong>Only &quot;not found&quot; moves on.</strong> If a remote answers 404, the next one is asked. If a remote times out or refuses the connection, the search stops and the client gets <strong>502</strong>: DepGate never silently falls back to the next remote (often a public registry). After repeated failures DepGate stops calling the remote for a short time; requests that remote would serve then get <strong>503</strong> with a <code>Retry-After</code> header, so package managers back off. The Decision Ledger records an <strong>Upstream unavailable</strong> entry.</li><li><strong>Put internal remotes first.</strong> When a public remote comes before an internal one, the form warns that a public package with one of your internal names would be taken from it, and the list marks the repository with a warning icon. <a href="./namespace-protection">Namespace protection</a> closes this gap completely.</li></ul><h2 id="remote-source" tabindex="-1">Remote source <a class="header-anchor" href="#remote-source" aria-label="Permalink to &quot;Remote source&quot;">​</a></h2><p>Each remote is either a <strong>Public registry</strong> or an <strong>Internal registry</strong>. The source matters in three places:</p><ul><li>Only internal remotes may serve names protected by a <a href="./namespace-protection">Namespace protection</a> policy (unless the policy says otherwise).</li><li>For public remotes, DepGate may look up a missing license or publish date on deps.dev, and Project health scores on the Scorecard API. For internal remotes it never does, so your internal package names never leave your network.</li><li>The form warns <em>This looks like a public registry</em> when a remote marked internal points at a well-known public host.</li></ul><p><code>default</code> is always public. A new remote must be given a source when it is created.</p><h2 id="effective-policies" tabindex="-1">Effective policies <a class="header-anchor" href="#effective-policies" aria-label="Permalink to &quot;Effective policies&quot;">​</a></h2><p><strong>Edit</strong> on a repository shows its <strong>Effective policies</strong>: every enabled policy that applies to it, in evaluation order. Use it to answer &quot;what happens to a package downloaded through this URL?&quot;.</p><h2 id="delete-a-repository" tabindex="-1">Delete a repository <a class="header-anchor" href="#delete-a-repository" aria-label="Permalink to &quot;Delete a repository&quot;">​</a></h2><p>Choose the trash icon. Before deleting, DepGate lists what changes: policies limited only to this repository are disabled (never widened to every repository), exceptions limited only to it are deleted, and pending waiver requests limited only to it are rejected.</p><p>Every change on this page is recorded in the <a href="./audit-log">Audit Log</a>.</p><h2 id="gateway-security" tabindex="-1">Gateway security <a class="header-anchor" href="#gateway-security" aria-label="Permalink to &quot;Gateway security&quot;">​</a></h2><p>The <strong>Gateway security</strong> card holds settings that apply to every repository:</p><table tabindex="0"><thead><tr><th>Setting</th><th>Description</th></tr></thead><tbody><tr><td><strong>Registry token lifetime</strong></td><td>How long the token in a developer&#39;s registry snippet stays valid. Default 30 days, at most 365; takes effect at the next sign-in. Browser sessions last 1 hour. A CI token lasts at most 1 day.</td></tr><tr><td><strong>Namespace collision check</strong></td><td>Daily check for your internal names on public registries. See <a href="./namespace-protection#collision-check-optional">Namespace protection</a>.</td></tr></tbody></table>',32)])])}const y=t(n,[["render",d]]);export{u as __pageData,y as default};
